using TMPro; using UnityEngine; using UnityEngine.Events; using UnityEngine.UI;
namespace ThinkingSpace.UI.DesignKit { public sealed class QuestUIActionCard:MonoBehaviour { [SerializeField] private string actionId; [SerializeField] private Button button; [SerializeField] private TMP_Text label; private UnityAction registeredAction; public string ActionId=>actionId; public Button Button=>button; public TMP_Text Label=>label; public void Configure(string id,Button value,TMP_Text text){actionId=id;button=value;label=text;} public void SetAction(UnityAction action){if(button==null)return;if(registeredAction!=null)button.onClick.RemoveListener(registeredAction);registeredAction=action;if(action!=null)button.onClick.AddListener(action);} } }
